// Explicit agency / brand / event scopes and a single creation flow.
function uiIcon(name){const paths={home:'M3 10l9-7 9 7v10H3z M9 20v-7h6v7',events:'M5 4h14v16H5z M8 8h8 M8 12h8 M8 16h5',workspace:'M3 7h18v13H3z M3 7V4h7l2 3',templates:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',whitelabel:'M4 6h16 M4 12h16 M4 18h16 M8 3v6 M16 9v6 M10 15v6',grip:'M9 5h.01 M15 5h.01 M9 12h.01 M15 12h.01 M9 19h.01 M15 19h.01',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z M9 12a3 3 0 1 0 6 0a3 3 0 1 0-6 0',hidden:'M3 3l18 18 M10 5h2c6 0 10 7 10 7l-3 4 M6 6l-4 6s4 7 10 7h2',text:'M4 5h16 M12 5v15 M8 20h8',game:'M4 7h16v12H4z M7 13h5 M9.5 10.5v5 M16 12h.01 M18 15h.01',button:'M3 7h18v10H3z',close:'M6 6l12 12 M18 6L6 18',heart:'M12 20L4 12C-1 6 7 1 12 7C17 1 25 6 20 12z'};return `<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.events}"/></svg>`}
navItem=function(r,t,k){const active=route()===r||(r==='workspace'&&route()==='workspace-detail');return `<a href="#${r}" class="${active?'active':''}">${uiIcon(k)}<span>${t}</span></a>`};
const eventRoutes=['editor','prizes','review','publish','checkout','operate','report'];
shell=function(body){const r=route(),b=currentBrand(),event=eventRoutes.includes(r);const crumb=event?`<a href="#workspace-detail" data-return-brand>${esc(b.name)}</a><span>/</span><strong>${esc(state.eventName||state.basic.name||'새 행사')}</strong>`:r==='workspace-detail'?`<a href="#workspace">브랜드 워크스페이스</a><span>/</span><strong>${esc(b.name)}</strong>`:esc(({home:'홈',events:'전체 행사',workspace:'브랜드 워크스페이스',templates:'게임 템플릿',whitelabel:'대행사 설정','event-basic':'행사 만들기',design:'디자인 보드'})[r]||'두잇킷');return `<div class="app-shell" data-frame="Console/1440"><aside class="sidebar"><a class="logo" href="#home"><b class="logo-mark">d.</b><span>두잇킷</span></a><div class="agency">스테이지원 커뮤니케이션</div>${btn('행사 만들기','new','wide')}<nav class="nav">${navItem('home','홈','home')}${navItem('events','전체 행사','events')}${navItem('workspace','브랜드 워크스페이스','workspace')}${navItem('templates','게임 템플릿','templates')}${navItem('whitelabel','대행사 설정','whitelabel')}</nav><div class="sidebar-bottom"><button data-action="usage" class="text-link plan">구독·사용량</button><div class="user"><div class="avatar">서</div><div>김서연<small><br>프로젝트 매니저</small></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumbs">${crumb}</div><div class="top-actions"><span class="demo-badge">DEMO</span><div class="avatar">서</div></div></header><div class="content">${body}</div></main></div>${index()}`};
const cleanHome=home;home=function(){return cleanHome().replace(/<td class="row-arrow">[\s\S]*?<\/td>/g,'').replace('<th></th>','').replace(/행사 만들기/g,'행사 만들기').replace('＋ ','')};
const cleanEvents=events;events=function(){return cleanEvents().replace(/<td class="row-arrow">[\s\S]*?<\/td>/g,'').replace('<th></th>','')};
state.wsTab='행사';
brandDetail=function(){const b=currentBrand();return shell(`<div class="brand-toolbar"><a href="#workspace" class="brand-back">브랜드 목록</a><select id="brand-switch" class="brand-switch" aria-label="브랜드 전환">${brandOptions()}</select></div>${title('',esc(b.name),'브랜드의 행사와 자료, 담당자를 관리합니다.',`<button class="btn" data-create="brand-create">행사 만들기</button>`)}<div class="editor-tabs">${['행사','브랜드 자료','멤버'].map(t=>`<button data-wstab="${t}" class="${state.wsTab===t?'active':''}">${t}</button>`).join('')}</div>${state.wsTab==='행사'?`<section class="panel"><div class="panel-head"><h2>진행 중·예정 행사</h2><span class="mini-label">${b.list.filter(v=>v[1]!=='종료').length}개</span></div>${brandRows({...b,list:b.list.filter(v=>v[1]!=='종료')},false).replace(/<td class="row-arrow">[\s\S]*?<\/td>/g,'').replace('<th></th>','')}</section>${b.list.some(v=>v[1]==='종료')?`<section class="panel mt"><h2>종료된 행사</h2>${brandRows({...b,list:b.list.filter(v=>v[1]==='종료')},false).replace(/<td class="row-arrow">[\s\S]*?<\/td>/g,'').replace('<th></th>','')}</section>`:''}`:state.wsTab==='브랜드 자료'?`<section class="panel brand-assets"><h2>브랜드 자료</h2><div class="field"><label for="brand-wordmark">로고 워드마크</label><input id="brand-wordmark" value="${esc(b.wordmark||b.name)}"></div><div class="field"><label for="workspace-color">대표 색상</label><input type="color" id="workspace-color" value="${b.color}"></div><button class="btn secondary" data-revision="save-brand">저장</button></section>`:`<section class="panel"><h2>브랜드 담당자</h2><p class="sub mt">초대할 담당자의 이메일을 입력하세요.</p><div class="inline mt"><input id="member-email" type="email" placeholder="이메일 주소" aria-label="담당자 이메일"><button class="btn secondary" data-revision="invite">초대</button></div><p class="mini-label mt">목업에서는 초대 요청을 시연하며 실제 메일은 발송되지 않습니다.</p></section>`}`)};
const cleanWorkspace=workspace;workspace=function(){return cleanWorkspace().replace('행사·발송·자료·게스트를 브랜드별로 관리합니다.','브랜드의 행사와 자료, 담당자를 관리할 수 있습니다.').replace(/<div class="helper mt">[\s\S]*?<\/div>/,'').replaceAll('워크스페이스 열기 →','워크스페이스 열기')};
state.newBrand='';state.pendingTemplate='';state.eventMemory={};state.settings={};state.pageLayers={};
function retainEvent(){if(state.eventName)state.eventMemory[state.brandId+'|'+state.eventName]=JSON.parse(JSON.stringify({layers:state.layers,pageLayers:state.pageLayers,selectedTemplate:state.selectedTemplate,consent:state.consent,approved:state.approved,paid:state.paid,published:state.published,basic:state.basic,settings:state.settings}))}
function beginEvent(brand=''){retainEvent();state.newBrand=brand;state.basic={name:'',start:'',end:'',type:'팝업스토어',place:'',channel:''};state.eventName='';go('event-basic')}
const cleanBasic=basicInfo;basicInfo=function(){return cleanBasic().replace(/<select id="basic-brand">[\s\S]*?<\/select>/,`<select id="basic-brand" required><option value="">브랜드 선택</option>${brands.map(b=>`<option value="${b.id}" ${state.newBrand===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select>`).replace('다음 · 게임 제작 →','저장').replace('새 행사를 시작해볼까요?','행사 기본 정보').replace('02　게임 제작','02　게임 선택·편집').replace('기본 정보는 게임 편집 화면에서도 다시 확인할 수 있습니다.','입력한 브랜드와 일정은 다음 단계에도 유지됩니다.')};
storeBasics=function(){state.basic={name:document.getElementById('event-name').value.trim(),start:document.getElementById('event-start').value,end:document.getElementById('event-end').value,type:document.getElementById('event-type').value,place:document.getElementById('event-place').value.trim(),channel:document.getElementById('event-channel')?.value||''};state.newBrand=document.getElementById('basic-brand').value};
const submitPrevious=submitBasics;submitBasics=function(e){e.preventDefault();storeBasics();if(!state.newBrand||!state.basic.name||!state.basic.start||!state.basic.end||!state.basic.channel)return toast('행사명, 브랜드, 운영 기간과 운영 방식을 입력해주세요.');if(state.basic.end<state.basic.start)return toast('종료일은 시작일 이후로 선택해주세요.');state.brandId=state.newBrand;state.eventName=state.basic.name;state.creationCustom=true;state.consent=false;state.approved=false;state.paid=false;state.published=false;state.ended=false;state.settings={};state.pageLayers={};state.layers=[];state.selectedTemplate='';state.gameDraft=null;state.gameDraftMode=false;state.paused=false;state.retried=false;state.aiLayerDraft='';state.layerHistory=[];state.createPrompt='';if(state.pendingTemplate){const id=state.pendingTemplate;state.pendingTemplate='';useTemplate(id)}else go('templates')};
const cleanTemplates=templates;templates=function(){let h=cleanTemplates();h=h.replace('어떤 행사를<br><em>만들고 싶으세요?</em>','어떤 게임을 만들까요?').replace('행사 아이디어를 알려주세요. 게임부터 경품까지, 함께 준비해요.','게임 아이디어를 입력하거나 아래 템플릿을 선택하세요.').replace(/<select id="create-brand"[\s\S]*?<\/select>/,`<span class="mini-label">${state.eventName?esc(state.eventName):'템플릿을 선택한 뒤 행사 정보를 입력합니다.'}</span>`).replace(/✧ AI로 행사 만들기 <span>↑<\/span>/,'게임 생성').replace('아이디어가 되는 게임들','게임 템플릿').replace('우리 브랜드에 맞게 바꿔보세요.','행사에 맞게 편집하세요.').replaceAll('02　게임 제작','02　게임 선택·편집');return h};
galleryCards=function(){const list=gameTemplates.filter(t=>(state.templateFilter==='전체'||state.templateFilter===t.category||(state.templateFilter==='즐겨찾기'&&state.favorites.includes(t.id)))&&`${t.title} ${t.type} ${t.desc}`.includes(state.templateSearch));return list.length?list.map(t=>`<article class="template-card" data-preview="${t.id}" tabindex="0" role="button" aria-label="${esc(t.title)} 미리보기">${templateStage(t)}<div class="template-info"><div class="template-meta"><span class="template-type">${t.type} · ${t.category}</span></div><h3>${t.title}</h3><p class="template-desc">${t.desc}</p><span class="text-link">미리보기</span></div></article>`).join(''):'<div class="empty-gallery">검색 결과가 없습니다.</div>'};
previewTemplate=function(id){const t=gameTemplates.find(t=>t.id===id);app.insertAdjacentHTML('beforeend',`<div class="modal-overlay"><div class="modal template-modal" role="dialog" aria-modal="true" aria-label="템플릿 미리보기">${templateStage(t,false)}<div><div class="between"><span class="mini-label">템플릿 미리보기</span><button data-create="close" aria-label="닫기">${uiIcon('close')}</button></div><h2>${t.title}</h2><p class="sub mt">${t.desc}</p><p class="small dim mt">제목, 안내 문구, 색상과 경품을 편집할 수 있습니다.</p><button class="btn wide mt" data-use="${id}">이 템플릿으로 만들기</button></div></div></div>`);bind()};
const resetPrevious=resetLayers;resetLayers=function(){resetPrevious();state.pageLayers={게임:state.layers};state.pageLayers['참여 시작']=JSON.parse(JSON.stringify(state.layers.filter(l=>l.id!=='game')));state.pageLayers['결과']=JSON.parse(JSON.stringify(state.layers.filter(l=>l.id!=='game')));state.pageLayers['결과'].find(l=>l.id==='title').text='축하합니다!\n선물이 도착했어요.';state.pageLayers['결과'].find(l=>l.id==='button').text='수령 안내 확인';state.studioPage='게임';state.layerHistory=[]};
useTemplate=function(id){if(!state.eventName){state.pendingTemplate=id;beginEvent();return}state.selectedTemplate=id;state.creationCustom=true;state.generated=false;state.applied=false;state.editorTab='디자인';state.aiLayerDraft='';resetLayers();go('editor');toast('선택한 템플릿을 편집합니다.')};
function switchStudioPage(page){state.pageLayers[state.studioPage]=state.layers;state.studioPage=page;state.layers=state.pageLayers[page]||state.layers;state.layerId=state.layers.some(l=>l.id===state.layerId)?state.layerId:state.layers[0].id;state.layerHistory=[];render()}
const cleanCanvas=layerCanvas;layerCanvas=function(){return cleanCanvas().replace(/축하합니다!\n선물이 도착했어요\./,esc(state.layers.find(l=>l.id==='title')?.text||''))};
steps=function(active){return `<div class="event-header"><h1>${esc(state.eventName||'새 행사')}</h1>${pill(state.ended?'종료':state.published?'진행 중':'작성 중',state.published?'':'draft')}</div><div class="steps">${[['editor','제작'],['review','검토'],['publish','게시'],['operate','운영'],['report','성과']].map(([r,t])=>`<button class="step ${active===r?'active':''}" data-event-step="${r}">${t}</button>`).join('')}</div>`};
function editorSections(){return `<div class="editor-tabs"><button data-editsection="디자인" class="${state.editorTab==='디자인'?'active':''}">게임 디자인</button><button data-editsection="수집·동의" class="${state.editorTab==='수집·동의'?'active':''}">참여 정보</button><button data-editsection="참여 규칙" class="${state.editorTab==='참여 규칙'?'active':''}">참여 규칙</button><button data-editsection="경품" class="${route()==='prizes'?'active':''}">경품·수령</button></div>`}
const cleanEditor=editor;editor=function(prizes=false){if(prizes||state.editorTab!=='디자인'){return shell(`${steps('editor')}${editorSections()}<div class="editor-grid"><section class="panel"><h2>${prizes?'경품·수령 설정':state.editorTab==='수집·동의'?'참여 정보·동의':state.editorTab}</h2>${prizes?prizeForm()+`<div class="field"><label for="pickup-location">현장 수령 장소</label><input id="pickup-location" value="${esc(state.settings.pickup||state.basic.place||'안내 데스크')}"></div>`:editorForm()}<div class="between mt"><button class="btn secondary" data-editsection="디자인">게임 디자인으로</button><button class="btn secondary" data-action="save">저장</button></div></section><aside class="preview-panel"><div class="preview-head">화면 미리보기</div>${layerCanvas()}</aside></div><div class="studio-bottom"><span class="mini-label">설정을 확인한 뒤 시안을 공유하세요.</span><button class="btn" data-action="to-review">검토 요청</button></div>`)}let h=cleanEditor(false);h=h.replace('<div class="studio-toolbar">',editorSections()+'<div class="studio-toolbar">').replace(/<div class="inline"><button class="btn secondary" data-studio="settings">[\s\S]*?<\/div><\/div>/,'</div>');h=h.replace(/<span class="layer-icon">[\s\S]*?<\/span>/g,'<span class="layer-icon">'+uiIcon('text')+'</span>').replace(/<button data-togglelayer="([^"]+)" aria-label="([^"]+)">[\s\S]*?<\/button>/g,(_,id,label)=>`<button data-togglelayer="${id}" aria-label="${label}">${uiIcon(state.layers.find(l=>l.id===id)?.visible?'eye':'hidden')}</button><button class="layer-grip" draggable="true" data-drag-layer="${id}" aria-label="${label.replace(' 표시 전환','')} 순서 이동" title="드래그로 순서 이동 · Alt+방향키">${uiIcon('grip')}</button>`).replace(/<div class="layer-controls">[\s\S]*?<\/div>/,'').replace('레이어를 선택하거나<br>화면 요소를 직접 클릭하세요.','요소를 클릭해 편집하세요. 드래그 핸들로 표시 순서를 바꿀 수 있습니다.').replace('✧ AI로 수정 요청하기','AI로 문구 수정').replace('검토로 이동 →','검토 요청').replace('← 다른 템플릿 선택','템플릿 변경').replace('텍스트·색상 변경은 즉시 반영됩니다.','선택한 요소의 설정을 변경하세요.');return h};
const oldEditorForm=editorForm;editorForm=function(){let h=oldEditorForm().replace('AI 초안 · 담당자 확인이 필요합니다.','수집 항목과 동의 내용을 확인하세요.').replace(/<div class="field"><label>게임 유형<\/label>[\s\S]*?<\/div>/,`<p class="mini-label">게임 유형: ${currentTemplate().type}</p>`);return h};
const cleanPublish=publish;publish=function(){return cleanPublish().replace('참여자를 만날 준비를 해요.','게시 전 확인').replace('행사 게시 →','행사 게시')};
const cleanCreateAction=createAction;createAction=function(a){if(a==='brand-create'){beginEvent(state.brandId);return}if(a==='generate'){const p=document.getElementById('create-prompt').value.trim();if(!p)return toast('게임 아이디어를 입력해주세요.');if(!state.eventName)return toast('먼저 행사 만들기에서 기본 정보를 입력해주세요.');state.createPrompt=p;const id=/스크래치/.test(p)?'nova-scratch':/퀴즈/.test(p)?'green-quiz':/메모리|카드/.test(p)?'violet-memory':/슬롯/.test(p)?'gold-slot':/반응|속도/.test(p)?'orange-speed':'lumiere-wheel';state.generatedTemplate=id;app.insertAdjacentHTML('beforeend',`<div class="modal-overlay"><div class="modal template-modal" role="dialog" aria-modal="true" aria-label="생성된 초안">${templateStage(gameTemplates.find(t=>t.id===id),false)}<div><div class="between"><span class="mini-label">생성된 초안</span><button data-create="close" aria-label="닫기">${uiIcon('close')}</button></div><h2>${gameTemplates.find(t=>t.id===id).title}</h2><p class="sub mt">입력한 설명과 맞는 템플릿을 바탕으로 준비한 시연 초안입니다.</p><button class="btn wide mt" data-use="${id}">이 초안 편집하기</button><button class="text-link mt" data-create="close">입력 내용 수정</button></div></div></div>`);bind();return}cleanCreateAction(a)};
const cleanStudioAction=studioAction;studioAction=function(a){if(a==='ai'){const p=document.getElementById('studio-prompt').value.trim(),m=p.match(/[‘'“"]([^’'”"]+)[’'”"]/);if(!m)return toast('바꿀 제목을 따옴표 안에 입력해주세요.');state.aiLayerDraft=m[1];render();return}cleanStudioAction(a)};
const cleanAction=action;action=function(a,n){if(a==='new'){state.pendingTemplate='';beginEvent();return}if(a==='brand-confirm'){cleanAction(a,n);state.wsTab='행사';render();return}if(a==='to-review'){if(!state.consent){state.editorTab='수집·동의';go('editor');toast('참여 정보의 동의 내용을 확인해주세요.');return}retainEvent();go('review');return}if(a==='save'){retainEvent();toast('변경 내용을 저장했습니다.');return}cleanAction(a,n)};
const openPrevious=openWorkspaceEvent;openWorkspaceEvent=function(n){retainEvent();state.wsTab='행사';const key=n.dataset.eventBrand+'|'+n.dataset.openEvent;openPrevious(n);if(state.eventMemory[key])Object.assign(state,state.eventMemory[key]);else{resetLayers();state.settings={};state.consent=state.approved;state.paid=state.published;state.aiLayerDraft=''}render()};
function reorderLayer(from,to){const i=state.layers.findIndex(l=>l.id===from),j=state.layers.findIndex(l=>l.id===to);if(i<0||j<0||i===j)return;snapshotLayers();const [l]=state.layers.splice(i,1);state.layers.splice(j,0,l);state.pageLayers[state.studioPage]=state.layers;render()}
const revisionBind=bind;bind=function(){revisionBind();app.querySelectorAll('[data-brand]').forEach(n=>n.onclick=e=>{e.preventDefault();enterBrandWorkspace(n.dataset.brand)});app.querySelectorAll('[data-studiopage]').forEach(n=>n.onclick=()=>switchStudioPage(n.dataset.studiopage));app.querySelectorAll('[data-preview]').forEach(n=>{n.onclick=e=>{if(e.target.closest?.('[data-favorite]'))return;previewTemplate(n.dataset.preview)};n.onkeydown=e=>{if(e.target!==n)return;if(e.key==='Enter'||e.key===' '){e.preventDefault();previewTemplate(n.dataset.preview)}}});app.querySelectorAll('[data-favorite]').forEach(n=>{const click=n.onclick;n.onclick=e=>{e.stopPropagation();click(e)}});app.querySelectorAll('[data-editsection]').forEach(n=>n.onclick=()=>{state.editorTab=n.dataset.editsection;go(state.editorTab==='경품'?'prizes':'editor')});app.querySelectorAll('[data-event-step]').forEach(n=>n.onclick=()=>{const r=n.dataset.eventStep;if(r==='review'){action('to-review');return}if(['operate','report'].includes(r)&&!state.published)return toast('행사를 게시한 뒤 이용할 수 있습니다.');retainEvent();go(r)});const sw=document.getElementById('brand-switch');if(sw)sw.onchange=()=>{enterBrandWorkspace(sw.value)};app.querySelectorAll('[data-drag-layer]').forEach(n=>{n.ondragstart=e=>{state.dragLayer=n.dataset.dragLayer;e.dataTransfer.setData('text/plain',state.dragLayer);e.dataTransfer.effectAllowed='move'};n.onkeydown=e=>{if(e.altKey&&['ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const i=state.layers.findIndex(l=>l.id===n.dataset.dragLayer),j=i+(e.key==='ArrowUp'?-1:1);if(state.layers[j])reorderLayer(n.dataset.dragLayer,state.layers[j].id)}}});app.querySelectorAll('.layer-item').forEach(n=>{n.ondragover=e=>{e.preventDefault();n.classList.add('drag-over')};n.ondragleave=()=>n.classList.remove('drag-over');n.ondrop=e=>{e.preventDefault();reorderLayer(e.dataTransfer.getData('text/plain'),n.querySelector('[data-drag-layer]').dataset.dragLayer)}});app.querySelectorAll('[data-revision]').forEach(n=>n.onclick=()=>{if(n.dataset.revision==='save-brand'){const b=currentBrand();b.wordmark=document.getElementById('brand-wordmark').value;b.color=document.getElementById('workspace-color').value;toast('브랜드 자료를 저장했습니다.')}else{const email=document.getElementById('member-email');if(!email.value||!email.checkValidity())return toast('이메일 주소를 확인해주세요.');toast(currentBrand().name+' 담당자 초대 요청 (시연): '+email.value)}});const pickup=document.getElementById('pickup-location');if(pickup)pickup.oninput=()=>state.settings.pickup=pickup.value;};
// The basic form needs the new submit handler after all bindings have been registered.
screens.find(s=>s[0]==='templates')[2]='게임 선택·템플릿';screens.find(s=>s[0]==='publish')[2]='게시 준비';screens.find(s=>s[0]==='whitelabel')[2]='대행사 설정';resetLayers();render();
layerCanvas=function(){const t=currentTemplate(),game=state.layers.find(l=>l.id==='game'),accent=game?.color||t.accent;return `<div class="editable-phone" data-component="EditableCanvas" style="--stage:${t.stage};--paper:${t.paper};--ink:${t.ink};--accent:${accent};background:${t.paper}">${state.layers.filter(l=>l.visible).map(l=>`<div data-layer="${l.id}" class="editable-layer ${l.id}-layer ${state.layerId===l.id?'selected':''}" style="${l.id==='game'?'':l.id==='button'?`background:${l.color};font-size:${l.size}px`:`color:${l.color};font-size:${l.size}px`}">${l.id==='game'?gameSketch(t):esc(l.text)}</div>`).join('')}</div>`};
const cleanStage=templateStage;templateStage=function(t,favorite=true){return cleanStage(t,favorite).replace(state.favorites.includes(t.id)?'♥':'♡',uiIcon('heart'))};
const boundRevision=bind;bind=function(){boundRevision();if(route()==='home'){app.querySelectorAll('[data-go]').forEach(n=>n.onclick=()=>{const statuses={operate:'진행 중',review:'검토 중',publish:'시작 예정'},e=eventData.find(v=>v[2]===statuses[n.dataset.go]);if(!e)return;openWorkspaceEvent({dataset:{eventBrand:brands.find(b=>b.short===e[1]).id,openEvent:e[0],eventStatus:e[2]}})})}const form=document.getElementById('basic-form');if(form)form.onsubmit=submitBasics;};
const oldReview=review;review=function(){return oldReview().replace('stageone.서비스도메인/lumiere/preview',esc(location.origin+location.pathname+'#brand-review')).replace('게시 준비 →','게시 준비')};
