const settingsForm=editorForm;editorForm=function(){let h=settingsForm();if(state.editorTab==='수집·동의'){h=h.replace('<textarea>',`<textarea id="consent-text">`);if(state.settings.consentText)h=h.replace(/(<textarea id="consent-text">)[\s\S]*?(<\/textarea>)/,`$1${esc(state.settings.consentText)}$2`)}if(state.editorTab==='참여 규칙')h=h.replace('<select>','<select id="entry-frequency">').replace(/<option>1일 1회<\/option><option>행사 기간 1회<\/option>/,`<option ${state.settings.frequency==='1일 1회'?'selected':''}>1일 1회</option><option ${state.settings.frequency==='행사 기간 1회'?'selected':''}>행사 기간 1회</option>`);return h};
const lastBind=bind;bind=function(){lastBind();const ct=document.getElementById('consent-text');if(ct)ct.oninput=()=>{state.settings.consentText=ct.value;state.consent=false;const check=document.getElementById('consent-check');if(check)check.checked=false};const freq=document.getElementById('entry-frequency');if(freq)freq.onchange=()=>state.settings.frequency=freq.value};
