const previewPhone=phone;phone=function(mode='game',large=false){if(mode==='game'&&['review','brand-review','editor','prizes'].includes(route()))return `<div class="review-canvas">${layerCanvas().replace(/ selected/g,'').replace(/data-layer="[^"]+"/g,'')}</div>`;return previewPhone(mode,large)};
const clearNavBind=bind;bind=function(){clearNavBind();app.querySelectorAll('.sidebar a[href="#templates"]').forEach(n=>n.onclick=e=>{e.preventDefault();retainEvent();state.eventName='';state.createPrompt='';go('templates')});app.querySelectorAll('[data-return-brand]').forEach(n=>n.onclick=e=>{e.preventDefault();retainEvent();state.wsTab='행사';go('workspace-detail')});};
const finalEditor=editor;editor=function(p=false){let h=finalEditor(p),i=0;return h.replace(/<span class="layer-icon">[\s\S]*?<\/span>/g,()=>{const l=state.layers[i++];return `<span class="layer-icon">${uiIcon(l?.id==='game'?'game':l?.id==='button'?'button':'text')}</span>`})};
